(() => {
  const app = window.__CITY_APP, C = window.CITY;
  const res = performance.getEntriesByType('resource').filter((e) => /geodata/.test(e.name))
    .map((e) => ({ file: e.name.split('/').pop(), bytes: e.encodedBodySize, ms: Math.round(e.responseEnd - e.startTime) }));
  if (res.some((r) => /toronto-geodata\.js/.test(r.file))) throw new Error('the 10.6 MB js/toronto-geodata.js was loaded');
  if (!res.some((r) => /toronto-geodata\.bin/.test(r.file))) throw new Error('data/toronto-geodata.bin was not fetched');
  const G = C.GEO;
  if (!(G.roadGraph.links.length > 0 && G.blocks.length > 0)) throw new Error('GEO is empty');
  const s = app.cullingStats || {};
  return { geodata: res, decodeMs: performance.getEntriesByName('geodata-decode').map((e) => +e.duration.toFixed(1)),
    links: G.roadGraph.links.length, blocks: G.blocks.length,
    culling: { mergedMeshes: s.mergedMeshes, mergedInto: s.mergedInto, proxyBuckets: s.proxyBuckets, gatedInstances: s.gatedInstances },
    names: { sugarBeach: C.getLocationLabel(1190, 520), eastBayfront: C.districtAt(1200, 500), harbourfront: C.districtAt(-400, 600), kingBay: C.districtAt(132, -350) } };
})()

(async () => {
  const app = window.__CITY_APP;
  app.teleportTo(60, 540, Math.atan2(-260, 35));
  const cam = { pos: [60, 2.2, 540], look: [-200, 1.5, 575], fov: 60 };
  app.cameraSystem.cinema = () => cam;
  await new Promise((r) => setTimeout(r, 7000));
  const i = app.renderer.info.render;
  return { label: window.CITY.getLocationLabel(60, 540), render: { drawCalls: i.drawCalls, calls: i.calls, triangles: i.triangles, frameCalls: i.frameCalls } };
})()

(() => {
  const app = window.__CITY_APP, B = app.transitBuses;
  if (!B) throw new Error('no transit buses');
  const pats = new Map();
  for (const r of B.routes) pats.set(r.pat, (pats.get(r.pat) || 0) + 1);
  const split = [...pats].filter(([, n]) => n > 1).map(([p, n]) => p.sign[0] + ' (' + n + ')');
  const r = B.routes.find((x) => x.pat.route === '6' || x.pat.route === 6) || B.routes[0];
  const e = r.links[Math.floor(r.links.length / 2)];
  app.selectMode('helicopter');
  app.teleportTo(e.sx, e.sz, 0);
  app.cameraSystem.cinema = () => ({ pos: [e.sx - 70, 90, e.sz + 70], look: [e.sx, 0, e.sz], fov: 50 });
  return { routePieces: B.routes.length, patternsMatched: pats.size, split, buses: B.routes.reduce((t, x) => t + x.buses.length, 0),
    shown: { route: r.pat.route, sign: r.sign.join(' / '), links: r.links.length, len: Math.round(r.len), stops: r.stops.length, of: r.pat.stops.length } };
})()

(() => {
  const app = window.__CITY_APP, cm = app.controllerManager;
  const out = { inventory: {} };
  for (const c of cm.colliders) if (c.prop) out.inventory[c.kind || 'other'] = (out.inventory[c.kind || 'other'] || 0) + 1;
  let clock = 5000;
  // a walker set 2.4 m out on the collider's axis (dir: unit vector from it), walking straight at it for 3 s
  function walkInto(c, dir) {
    const cx = c.circle ? c.circle.x : c.obb ? c.obb.cx : (c.minX + c.maxX) / 2, cz = c.circle ? c.circle.z : c.obb ? c.obb.cz : (c.minZ + c.maxZ) / 2;
    const x = cx + dir[0] * 2.4, z = cz + dir[1] * 2.4, heading = Math.atan2(-dir[0], -dir[1]);
    if (!cm.findTeleportPosition(x, z, heading, 0, true)) return null;
    app.selectMode('person');
    const e = cm.getActiveEntity();
    cm.resetInput();
    e.position.set(x, cm.getGroundHeight(x, z, 'person'), z);
    e.heading = heading; e.speed = 0;
    for (const k of ['vx', 'vz', 'angularVel', 'verticalSpeed', 'verticalVel']) if (k in e) e[k] = 0;
    e.mesh.position.copy(e.position);
    cm.lastWorldContact = null;
    cm.keys.forward = true;
    let closest = Infinity;
    for (let i = 0; i < 180; i++) {
      e.heading = heading;
      cm.update(1 / 60, (clock += 1 / 60));
      closest = Math.min(closest, (e.position.x - cx) * dir[0] + (e.position.z - cz) * dir[1]);
    }
    cm.resetInput();
    const hit = cm.lastWorldContact && cm.lastWorldContact.collider;
    return { kind: c.kind, at: [Math.round(cx), Math.round(cz)], closestAlongAxis: Math.round(closest * 100) / 100, stoppedBy: hit ? (hit === c ? 'it' : hit.kind || 'other') : 'nothing' };
  }
  const near = (kind, x, z) => cm.colliders.filter((c) => c.prop && c.kind === kind)
    .map((c) => ({ c, d: Math.hypot((c.circle ? c.circle.x : c.obb ? c.obb.cx : (c.minX + c.maxX) / 2) - x, (c.circle ? c.circle.z : c.obb ? c.obb.cz : (c.minZ + c.maxZ) / 2) - z) }))
    .sort((a, b) => a.d - b.d).slice(0, 40).map((o) => o.c);
  const dirsFor = (c) => c.obb ? [[c.obb.sn, c.obb.cs], [-c.obb.sn, -c.obb.cs]] : [[1, 0], [0, 1], [-1, 0], [0, -1]];
  out.walks = {};
  for (const kind of ['hydrant', 'litterBin', 'postBox', 'bench', 'parkingMeter']) {
    for (const c of near(kind, 132, -350)) {
      let r = null;
      for (const d of dirsFor(c)) if ((r = walkInto(c, d)) && r.stoppedBy === 'it') break;
      if (r && r.stoppedBy === 'it') { out.walks[kind] = r; break; }
    }
    if (!out.walks[kind]) throw new Error('no clear walk into a ' + kind + ' near King & Bay stopped at it');
    // never through: the walker's middle stays outside the furniture (the slim body: 0.3 m)
    if (!(out.walks[kind].closestAlongAxis > 0.2)) throw new Error(kind + ': walked through (' + out.walks[kind].closestAlongAxis + ')');
  }
  const w = out.walks.hydrant, hx = w.at[0], hz = w.at[1];
  app.teleportTo(hx + 3, hz + 3, Math.PI);
  const p = cm.getActiveEntity().position;
  app.cameraSystem.cinema = () => ({ pos: [hx + 7, p.y + 6, hz + 9], look: [hx, p.y + 0.6, hz], fov: 50 });
  return out;
})()

(() => {
  const a = window.__CITY_APP;
  a.cameraSystem.cinema = null;
  document.getElementById('locate-prompt') && (document.getElementById('locate-prompt').hidden = true);
  if (!a.rideFeatured('504')) throw new Error('featured 504 ride did not start');
  const R = a.streetcarRide;
  if (!R.active) throw new Error('not riding');
  return { active: R.active, car: R.car && (R.car.id ?? null) };
})()
